// Les Trois Clefs d'Aiguemorne · act IV, the coup (1/3): the plan at the dice (jeu), led by the voice, on the evening
// of the 7th of November. Three beats around two hinges (A4c_signal_jeu, A4c_des_jeu).
// First beat: monde:a4:mise=billets|clefs (what lies on the green cloth), monde:a4:c_voix (the count lets the voice
// throw), monde:a4:c_main (the Syndic's note never reached the Dean), monde:a4:c_oeil (the gallery and its chandelier
// winch are held). Second beat: monde:a4:k=gagne|perdu|triche|rompu. Personal: a4:v_des (the leaded dice), a4:v_triche.
// Result (set at A4c_des_jeu): monde:a4:clef=gagnee (+ monde:brandelis:parole) or prise (taken back that night).
// Also monde:a4:comte_libre (his notes burnt or given back), monde:a4:hyacinthe_doute, monde:a4:comte_sait.
// Everything ends at A4c_apres (a4_suite).
var POSTE = function (m, o, v) { return [{ if: { role: "a4", is: "main" }, to: m }, { if: { role: "a4", is: "oeil" }, to: o }, { to: v }]; };
var BILLETS = { has: "monde:a4:mise=billets" };
var CLEFS = { not: "monde:a4:mise=billets" };
// What the voice still has to go through before the dice, in the second beat.
var APRES_TERMES = [{ if: { not: "monde:a4:c_main" }, to: "A4v_jeu_doyen" }, { if: { not: "monde:a4:c_oeil" }, to: "A4v_jeu_noir" }, { to: "A4v_jeu_des" }];
var APRES_DOYEN = [{ if: { not: "monde:a4:c_oeil" }, to: "A4v_jeu_noir" }, { to: "A4v_jeu_des" }];
